"""Toolkit for probing /workspace/executable (elfcat).

Usage:
    import sys; sys.path.insert(0, '/tmp/kit')
    from elfkit import *
    h = run(build(phdrs=[dict(ptype=1, off=0x100, filesz=0x10)], filesize=0x200))
    print(fileinfo(h))
    print(itable(h, 'info_phdr0'))
    show_ranges(h)
"""
import struct, os, re, subprocess, tempfile

EXE = '/workspace/executable'

# ---------------- ELF construction ----------------

def ehdr(bits=64, **kw):
    d = dict(magic=b'\x7fELF', bitness=(2 if bits == 64 else 1), endian=1, ident_ver=1,
             osabi=0, abiver=0, pad=b'\x00' * 7, etype=2,
             machine=(0x3e if bits == 64 else 3), version=1, entry=0x1000, phoff=0,
             shoff=0, flags=0, ehsize=(64 if bits == 64 else 52),
             phentsize=(56 if bits == 64 else 32), phnum=0,
             shentsize=(64 if bits == 64 else 40), shnum=0, shstrndx=0)
    d.update(kw)
    ei = d['magic'] + bytes([d['bitness'], d['endian'], d['ident_ver'], d['osabi'],
                             d['abiver']]) + d['pad']
    e = '<' if d['endian'] == 1 else '>'
    fmt = e + ('HHIQQQIHHHHHH' if bits == 64 else 'HHIIIIIHHHHHH')
    return ei + struct.pack(fmt, d['etype'] & 0xffff, d['machine'] & 0xffff,
                            d['version'] & 0xffffffff, d['entry'], d['phoff'], d['shoff'],
                            d['flags'] & 0xffffffff, d['ehsize'], d['phentsize'], d['phnum'],
                            d['shentsize'], d['shnum'], d['shstrndx'])

def phdr(bits=64, endian=1, ptype=1, flags=4, off=0, vaddr=0, paddr=0, filesz=0, memsz=0,
         align=0):
    e = '<' if endian == 1 else '>'
    if bits == 64:
        return struct.pack(e + 'IIQQQQQQ', ptype & 0xffffffff, flags & 0xffffffff, off,
                           vaddr, paddr, filesz, memsz, align)
    return struct.pack(e + 'IIIIIIII', ptype & 0xffffffff, off, vaddr, paddr, filesz,
                       memsz, flags & 0xffffffff, align)

def shdr(bits=64, endian=1, name=0, stype=1, flags=0, addr=0, off=0, size=0, link=0,
         info=0, align=0, entsize=0):
    e = '<' if endian == 1 else '>'
    if bits == 64:
        return struct.pack(e + 'IIQQQQIIQQ', name, stype & 0xffffffff, flags, addr, off,
                           size, link, info, align, entsize)
    return struct.pack(e + 'IIIIIIIIII', name, stype & 0xffffffff, flags, addr, off, size,
                       link, info, align, entsize)

def build(phdrs=(), shdrs=(), filesize=None, bits=64, endian=1, fill=None, patch=None,
          phoff=None, shoff=None, **ehkw):
    """Build an ELF. phdrs/shdrs are lists of kwargs dicts.
    patch: list of (offset, bytes) applied at the end."""
    ehsz = 64 if bits == 64 else 52
    phes = 56 if bits == 64 else 32
    shes = 64 if bits == 64 else 40
    phes = ehkw.get('phentsize', phes)
    shes = ehkw.get('shentsize', shes)
    if phoff is None:
        phoff = ehsz if phdrs else 0
    if shoff is None:
        shoff = (ehsz + phes * len(phdrs)) if shdrs else 0
    kw = dict(endian=endian, ehsize=ehsz, phentsize=phes, shentsize=shes,
              phnum=len(phdrs), shnum=len(shdrs), phoff=phoff, shoff=shoff)
    kw.update(ehkw)
    data = bytearray(ehdr(bits=bits, **kw))
    for p in phdrs:
        data += phdr(bits=bits, endian=endian, **p)
    for s in shdrs:
        data += shdr(bits=bits, endian=endian, **s)
    if filesize is not None:
        if filesize > len(data):
            f = fill if fill is not None else bytes(range(256)) * (filesize // 256 + 1)
            data += f[:filesize - len(data)]
        else:
            data = data[:filesize]
    if patch:
        for off, b in patch:
            if off + len(b) > len(data):
                data += b'\x00' * (off + len(b) - len(data))
            data[off:off + len(b)] = b
    return bytes(data)

# ---------------- running ----------------

_dir = None

def workdir():
    global _dir
    if _dir is None:
        _dir = tempfile.mkdtemp(prefix='elfkit')
    return _dir

def run(data, name='p.bin', raise_on_err=False):
    """Run elfcat on `data`. Returns html string, or raises/returns None on failure.
    Access last error via run.err"""
    d = workdir()
    p = os.path.join(d, name)
    with open(p, 'wb') as f:
        f.write(data)
    out = p + '.html'
    if os.path.exists(out):
        os.unlink(out)
    r = subprocess.run([EXE, name], cwd=d, capture_output=True)
    run.err = (r.stdout + r.stderr).decode('utf-8', 'replace')
    run.code = r.returncode
    if r.returncode != 0:
        if raise_on_err:
            raise RuntimeError(run.err)
        return None
    return open(out, encoding='utf-8').read()
run.err = ''
run.code = 0

def err(data, **kw):
    h = run(data, **kw)
    return run.err.strip() if h is None else None

# ---------------- html extraction ----------------

def div(html, key):
    i = html.index("<div id='%s'>" % key) + len("<div id='%s'>" % key)
    j = html.index("</div>", i)
    return html[i:j]

def fileinfo(html):
    """dict of fileinfo_<cls> -> inner html of 2nd td"""
    out = {}
    for m in re.finditer(r"<tr class='fileinfo_([a-z_0-9]+)'> <td>([^<]*)</td> <td>(.*?)</td> </tr>", html):
        out[m.group(1)] = (m.group(2), m.group(3))
    return out

def itable(html, tid):
    m = re.search(r"<table class='conceal itable' id='%s'>\n(.*?)\n          </table>" % tid, html, re.S)
    return m.group(1) if m else None

def itables(html):
    out = {}
    for m in re.finditer(r"<table class='conceal itable' id='([a-z_0-9]+)'>\n(.*?)\n          </table>", html, re.S):
        out[m.group(1)] = m.group(2)
    return out

def itable_rows(html, tid):
    t = itable(html, tid)
    if t is None:
        return None
    return re.findall(r"<tr> <td>(.*?)</td> <td>(.*?)</td> </tr>", t)

def connects(html):
    return re.findall(r"^      connect\('(.*?)', '(.*?)'\);$", html, re.M)

def highlights(html):
    return re.findall(r"^      highlightClasses\('(.*?)', '(.*?)'\)$", html, re.M)

FIELDS = set(('magic class data ver abi abi_ver pad e_type e_machine e_version e_entry '
              'e_phoff e_shoff e_flags e_ehsize e_phentsize e_phnum e_shentsize e_shnum '
              'e_shstrndx p_type p_flags p_offset p_vaddr p_paddr p_filesz p_memsz '
              'p_align sh_name sh_type sh_flags sh_addr sh_offset sh_size sh_link sh_info '
              'sh_addralign sh_entsize ident ehdr').split())

def span_ranges(html):
    """Reconstruct lexical span nesting from #bytes. Returns (list of (start,end,depth,cls), total)."""
    body = div(html, 'bytes')
    toks = re.split(r"(<span class='[^']*'>|</span>)", body)
    stack = []; off = 0; out = []
    for t in toks:
        if t.startswith('<span'):
            stack.append((off, re.match(r"<span class='([^']*)'>", t).group(1), len(stack)))
        elif t == '</span>':
            s, c, dp = stack.pop()
            out.append((s, off, dp, c))
        else:
            off += len(re.findall(r"(?:[0-9a-f]{2}|&nbsp;.)", t))
    out.sort(key=lambda r: (r[0], r[2]))
    return out, off

def show_ranges(html, fields=False):
    rs, total = span_ranges(html)
    for s, e, d, c in rs:
        if not fields and c in FIELDS:
            continue
        print("  %s0x%x..0x%x  %s" % ('  ' * d, s, e, c))
    print("  total=%d" % total)

def open_close_events(html):
    """Return the raw sequence of (byte_offset, '+'/'-', class_or_None) in lexical order."""
    body = div(html, 'bytes')
    toks = re.split(r"(<span class='[^']*'>|</span>)", body)
    off = 0; out = []
    for t in toks:
        if t.startswith('<span'):
            out.append((off, '+', re.match(r"<span class='([^']*)'>", t).group(1)))
        elif t == '</span>':
            out.append((off, '-', None))
        else:
            off += len(re.findall(r"(?:[0-9a-f]{2}|&nbsp;.)", t))
    return out

def starts_at(html):
    """map offset -> list of classes opened there, in lexical order"""
    out = {}
    for off, k, c in open_close_events(html):
        if k == '+':
            out.setdefault(off, []).append(c)
    return out

def ends_at(html):
    out = {}
    for off, k, c in open_close_events(html):
        if k == '-':
            out[off] = out.get(off, 0) + 1
    return out

