import sys, time
sys.path.insert(0,'/tmp/kit'); sys.path.insert(0,'/tmp/shtype_scratch')
from bulk import bulk

CH=32768
def sweep(vals, label):
    vals=[v & 0xffffffff for v in vals]
    found={}
    bad=[]
    for i in range(0, len(vals), CH):
        chunk=vals[i:i+CH]
        r,_=bulk(chunk)
        for v in chunk:
            s=r.get(v)
            if s is None: bad.append(v); continue
            if s != 'Unknown: %d' % v:
                found[v]=s
    print("### %s : n=%d  named=%d  missing=%d" % (label, len(vals), len(found), len(bad)))
    for v in sorted(found): print("   0x%08x %-12d %s" % (v,v,found[v]))
    if bad: print("   MISSING:", [hex(x) for x in bad[:20]])
    return found

if __name__=='__main__':
    all_found={}
    jobs=[]
    jobs.append((range(0,0x10000), "0x0..0xffff exhaustive"))
    jobs.append((range(0,0x100000000,0x10000), "full 32-bit, stride 0x10000"))
    jobs.append((range(0x60000000,0x70000000,0x100), "OS range stride 0x100"))
    jobs.append((range(0x70000000,0x80000000,0x100), "PROC range stride 0x100"))
    jobs.append((range(0x80000000,0x90000000,0x100), "USER range stride 0x100"))
    for b in (0x60000000,0x6ffe0000,0x6fff0000,0x70000000,0x7ffe0000,0x7fff0000,0x80000000,0x8fff0000,0xffff0000):
        jobs.append((range(b,b+0x10000), "dense 0x%08x..+0xffff"%b))
    t0=time.time()
    for vals,label in jobs:
        f=sweep(list(vals), label); all_found.update(f)
    print("\n=== UNION of all named values (%d) ===" % len(all_found))
    for v in sorted(all_found): print("0x%08x  %-12d  %s" % (v,v,all_found[v]))
    print("elapsed %.1fs" % (time.time()-t0))
EOF
